{
  "reviews": [
    {
      "decision": "keep",
      "id": "C001",
      "reason": "名称'Scribble'易读、易记，符合口头交流需求；'scribble'在语义上暗示草稿、快速记录，与字幕草稿修改场景有弱关联，但未明确指向比较功能。虽未直接表达‘比较’，但整体简洁专业，符合‘不夸大智能能力’的简报要求。读写清晰，无歧义，可作为团队口头交流用名。"
    },
    {
      "decision": "hold",
      "id": "C002",
      "reason": "名称'Diffly'由'difference'与'fly'组合，意为‘快速查看差异’，直接呼应功能意图，且发音简洁、易记。'fly'在口语中常被理解为‘快速’，但该词在语义上可能被误解为‘飞行’或‘轻飘’，与字幕修改无直接联想。虽功能相关，但缺乏对‘字幕’或‘编辑’场景的锚定，存在潜在误解风险。需进一步验证用户认知是否与功能匹配。"
    },
    {
      "decision": "keep",
      "id": "C003",
      "reason": "名称'LineTap'由'line'与'tap'构成，明确指向‘行级查看’，符合‘线性字幕’和‘快速检查’的使用场景，语言直观，易于口头传达。'tap'暗示交互动作，与剪辑团队的实时操作习惯契合。名称具体、可读性强，未夸大能力，符合离线工具的轻量、实用定位。"
    },
    {
      "decision": "hold",
      "id": "C004",
      "reason": "名称'SideBy'源自‘side-by-side’，明确表达对比功能，语义清晰。但名称过短，'SideBy'在口语中易被误解为‘side by’（如‘side by side’的缩略），可能引发歧义。'By'在英语中常作介词，非独立名词，导致命名在口头交流中可能不自然，需确认团队是否能自然接受该名称。"
    },
    {
      "decision": "keep",
      "id": "C005",
      "reason": "名称'Textal'由'text'与'anal'构成，'anal'虽为‘analysis’缩写，但易被误解为‘anal’（俚语或性暗示），在专业语境中存在潜在负面联想，可能影响团队接受度。尽管语义上可理解为‘文本分析’，但其常见读法和文化联想风险较高，需谨慎评估。目前保留以供观察，但非推荐首选。"
    },
    {
      "decision": "keep",
      "id": "C006",
      "reason": "名称'Sublyte'由'subtitle'与'lite'组成，直接关联字幕与轻量工具，语义明确、专业，且符合‘离线’、‘轻量’的使用场景。'lite'在技术语境中常表示轻量，无歧义，名称易读、易记，适合团队口头交流。虽未直接表达‘比较’功能，但通过上下文可推断其用途，符合简报要求。"
    }
  ]
}

